WITH matched_keys AS (SELECT browser FROM sessions INTERSECT ALL SELECT browser FROM sessions WHERE device IN ('mobile', 'tablet')), verified AS (SELECT s.* FROM sessions s JOIN matched_keys k ON s.browser = k.browser) SELECT customer_id, device, browser, COUNT(*) AS cnt, SORT_ARRAY(COLLECT_SET(device)) AS device_list, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM verified GROUP BY customer_id, device, browser HAVING distinct_customer_ids >= 1 ORDER BY browser DESC;
